/**
 * Live-signal bridge.
 *
 * A Horizon app cannot subscribe to the domain call / agent / queue / contacts
 * feeds the Engage switchboard uses (those live on the :8001 socket, and the
 * app has no credential for it). What an app CAN receive is a host-relayed
 * stream, each gated by a `<stream>:listen` permission. Only one is granted:
 *
 *   call-events   the signed-in user's own call lifecycle
 *
 * It is not the domain-wide board feed, but each event is a hint that
 * something changed, so it is re-emitted as one signal on the app's event bus
 * and the data provider pulls its next poll forward.
 *
 * Why not `device`, `registration` and `subscriber` as well: this Horizon build
 * (46.0.1) gives every app the same fixed permission list (`mapDbAppToSdkApp`
 * assigns `DEFAULT_APP_PERMISSIONS`), which carries `call-events:listen` and
 * none of the other three, whatever the verification report extracted. So a
 * subscription to them is always refused, and each refusal is a red error in
 * the browser console of every operator. Verified live on the lab. Add them back
 * once the host starts granting capability permissions; write each stream id as
 * a literal at its own call site, because the platform analyser reads string
 * literals to find the capabilities an app declares.
 */
import type { RemoteAppSDK } from '@netsapiens/horizon-sdk';

/** The event-bus key the data provider listens on. */
export const LIVE_SIGNAL_EVENT = 'switchboard:live-signal';

export interface LiveSignal {
  stream: 'call-events';
  type?: string;
  at: number;
}

type EventBus = { emit: (event: string, data?: unknown) => void };

export function installLiveSignals(sdk: RemoteAppSDK, eventBus: EventBus): () => void {
  let off: (() => void) | null = null;
  try {
    off = sdk.subscribeToCallEvents(['call-started', 'call-answered', 'call-missed', 'call-ended'], (event) =>
      eventBus.emit(LIVE_SIGNAL_EVENT, { stream: 'call-events', type: event.type, at: Date.now() } satisfies LiveSignal),
    );
  } catch (e) {
    console.warn('[switchboard] call-events stream unavailable:', e);
  }
  return () => {
    try {
      off?.();
    } catch {
      /* best effort */
    }
  };
}
