/**
 * Call handling: one extension's answering rules (NetSapiens "answer rules"),
 * read and edited through the v2 API.
 *
 * Shape, confirmed on a v46 switch (all 78 users of two test domains,
 * 2026-09-24): one rule per time frame,
 *   { time-frame: "*", domain, user, is-active: true, ordinal-priority: 0,
 *     enabled: "yes", simultaneous-ring: { enabled: "yes", parameters: ["<OwnDevices>"] } }
 * The switch OMITS an option that is off, so an absent option reads as off.
 * Every lab user had only that default rule, so the rest of the option
 * vocabulary comes from the Horizon host's own answer-rule form schema (v46):
 * do-not-disturb and call-screening are `{enabled}`; forward-always,
 * forward-on-active, forward-on-busy, forward-no-answer,
 * forward-when-unregistered, forward-on-spam-call, phone-numbers-to-reject and
 * simultaneous-ring are `{enabled, parameters: (string | number)[]}`.
 * Simultaneous-ring entries may carry a `;delay=N` suffix. Anything else the
 * switch returns in `{enabled, ...}` form (forward-on-dnd,
 * phone-numbers-to-allow, or something newer) is shown read-only.
 *
 * Saving PUTs the WHOLE rule, the way Horizon's own answer-rule editor does:
 * every option explicit (an off option as `{enabled: "no"}`), the edited ones
 * at their new values and the rest echoed exactly as the switch returned them.
 * That gives the same result whether the switch merges a PUT into the rule or
 * replaces the rule with it, which could not be tested on the lab. Then the
 * rules are re-read: the switch accepts a PUT before applying it, so the
 * re-read is what confirms the change landed. Rules are not created,
 * reordered or deleted here.
 */
import type * as React from 'react';
import { useEffect, useRef, useState } from 'react';

import type { NsAnswerRule, NsRecord } from '../types';
import * as ns from '../api/ns';
import { useSwitchboard } from '../data/SwitchboardData';
import { useActions } from '../data/actions';
import { classifyError, describeError, describeReadError } from '../model/errors';
import { explicitNo, lower, pick, str, toIntOrUndef, userPart, yes } from '../model/raw';
import { useKit } from '../ui/kit';
import { Empty, Pill, SmallButton } from '../ui/bits';

// ---------------------------------------------------------------------------
// Option vocabulary
// ---------------------------------------------------------------------------

const SIM_RING = 'simultaneous-ring';
const DND = 'do-not-disturb';
const OWN_DEVICES = '<OwnDevices>';
const OWN_DEVICES_LABEL = 'Your devices';

interface OptionDef {
  key: string;
  label: string;
  hint: string;
  /** Whether the option takes destinations, and how many. */
  params: 'none' | 'one' | 'many';
  field?: { label: string; placeholder: string; helper: string };
}

const FORWARD_FIELD = {
  label: 'Forward to',
  placeholder: '1002, +18135550142 or user@domain',
  helper: 'An extension, a phone number or user@domain.',
};

const OPTIONS: OptionDef[] = [
  { key: DND, label: 'Do not disturb', hint: 'Sends every caller to voicemail.', params: 'none' },
  { key: 'forward-always', label: 'Forward always', hint: 'Sends every call straight to the destination.', params: 'one', field: FORWARD_FIELD },
  {
    key: SIM_RING,
    label: 'Simultaneous ring',
    hint: 'The phones that ring together when a call comes in.',
    params: 'many',
    field: {
      label: 'Ring',
      placeholder: `${OWN_DEVICES_LABEL}, 1002`,
      helper: `Separate with commas. "${OWN_DEVICES_LABEL}" means every phone on this extension.`,
    },
  },
  { key: 'forward-on-active', label: 'Forward when on a call', hint: 'Forwards new calls while this extension is on another call.', params: 'one', field: FORWARD_FIELD },
  { key: 'forward-on-busy', label: 'Forward when busy', hint: 'Forwards when the line is busy.', params: 'one', field: FORWARD_FIELD },
  { key: 'forward-no-answer', label: 'Forward when unanswered', hint: 'Forwards calls that are not answered.', params: 'one', field: FORWARD_FIELD },
  { key: 'forward-when-unregistered', label: 'Forward when offline', hint: 'Forwards when the phone is offline.', params: 'one', field: FORWARD_FIELD },
  { key: 'forward-on-spam-call', label: 'Forward suspected spam', hint: 'Forwards calls flagged as likely spam.', params: 'one', field: FORWARD_FIELD },
  { key: 'call-screening', label: 'Call screening', hint: 'Asks callers to say their name before the call rings through.', params: 'none' },
  {
    key: 'phone-numbers-to-reject',
    label: 'Reject numbers',
    hint: 'Refuses calls from these numbers.',
    params: 'many',
    field: { label: 'Numbers', placeholder: '+18135550142, 8135550199', helper: 'Separate numbers with commas.' },
  },
];

const OPTION_KEYS = new Set(OPTIONS.map((o) => o.key));

/** Options the switch may return that this panel shows but does not change. */
const READ_ONLY_LABELS: Record<string, string> = {
  'forward-on-dnd': 'Forward on do not disturb',
  'phone-numbers-to-allow': 'Allow numbers',
};

const FRAME_TYPE: Record<string, string> = {
  always: 'always',
  'days-of-week': 'days of the week',
  'specific-dates': 'specific dates',
  holiday: 'holidays',
  custom: 'custom schedule',
};

// ---------------------------------------------------------------------------
// Reading rules
// ---------------------------------------------------------------------------

type Param = string | number;

interface OptionState {
  on: boolean;
  params: Param[];
}

function readOption(rule: NsRecord | undefined, key: string): OptionState {
  const v = rule?.[key];
  if (!v || typeof v !== 'object' || Array.isArray(v)) return { on: false, params: [] };
  const o = v as { enabled?: unknown; parameters?: unknown };
  const params = Array.isArray(o.parameters)
    ? o.parameters.filter((p): p is Param => (typeof p === 'string' && p.trim() !== '') || typeof p === 'number')
    : [];
  return { on: yes(o.enabled), params };
}

/** A rule with no `enabled` field is treated as on (only an explicit "no" is off). */
function ruleEnabled(rule: NsRecord): boolean {
  return !explicitNo(rule.enabled);
}

function frameOf(rule: NsRecord): string {
  return str(rule['time-frame']).trim();
}

function frameLabel(tf: string): string {
  if (tf === '*') return 'Default (always)';
  return tf || 'Unnamed rule';
}

function optionLabel(key: string): string {
  return OPTIONS.find((o) => o.key === key)?.label ?? READ_ONLY_LABELS[key] ?? humanize(key);
}

function humanize(key: string): string {
  const s = key.replace(/[-_]+/g, ' ').trim();
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : key;
}

/** Option-shaped entries the panel does not edit: `{enabled, ...}` objects under other keys. */
function extraOptionKeys(rule: NsRecord): string[] {
  return Object.keys(rule).filter((k) => {
    if (OPTION_KEYS.has(k)) return false;
    const v = rule[k];
    return !!v && typeof v === 'object' && !Array.isArray(v) && 'enabled' in v;
  });
}

/** In the order the phone system checks them (`ordinal-priority`, lowest first). */
function sortRules(rows: NsAnswerRule[]): NsAnswerRule[] {
  return rows
    .map((r, i) => ({ r, i, p: toIntOrUndef(r['ordinal-priority']) ?? Number.POSITIVE_INFINITY }))
    .sort((a, b) => (a.p === b.p ? a.i - b.i : a.p - b.p))
    .map((x) => x.r);
}

// ---------------------------------------------------------------------------
// When a rule applies
// ---------------------------------------------------------------------------

interface FrameInfo {
  type: string;
  personal: boolean;
}

function indexFrames(rows: NsRecord[], user: string): Map<string, FrameInfo> {
  const m = new Map<string, FrameInfo>();
  for (const r of rows) {
    const name = pick(r, 'timeframe-name', 'time-frame', 'name');
    if (!name || m.has(name)) continue;
    m.set(name, { type: lower(pick(r, 'timeframe-type', 'type')), personal: userPart(r.user) === user });
  }
  return m;
}

const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

const dayFmt = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });

function clockLabel(hhmm: string): string {
  const m = /^(\d{1,2}):(\d{2})/.exec(hhmm);
  if (!m) return hhmm;
  const h = Number(m[1]);
  return `${h % 12 || 12}:${m[2]} ${h >= 12 ? 'PM' : 'AM'}`;
}

function dateLabel(v: string): string {
  const m = /^(\d{4})-?(\d{2})-?(\d{2})$/.exec(v.trim());
  return m ? dayFmt.format(new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])))) : v;
}

/** "Monday", "Monday to Friday" (a run of three or more), or "Monday, Wednesday". */
function daysLabel(days: number[]): string {
  const list = Array.from(new Set(days)).sort((a, b) => a - b);
  const run = list.length >= 3 && list.every((d, i) => i === 0 || d === list[i - 1] + 1);
  return run ? `${DAYS[list[0]]} to ${DAYS[list[list.length - 1]]}` : list.map((d) => DAYS[d]).join(', ');
}

/**
 * "Monday to Friday, 9:00 AM to 5:00 PM" from a rule's `time_range_data`, when
 * the switch sends it. Ranges that share dates and hours are grouped by day.
 */
function scheduleSummary(v: unknown): string {
  if (!Array.isArray(v) || !v.length) return '';
  const groups = new Map<string, { dates: string; times: string; days: number[]; everyDay: boolean }>();
  for (const r of v) {
    if (!r || typeof r !== 'object' || Array.isArray(r)) continue;
    const rec = r as NsRecord;
    const sd = str(rec['start-date']).trim();
    const ed = str(rec['end-date']).trim();
    const st = str(rec['start-time']).trim();
    const et = str(rec['end-time']).trim();
    const dow = str(rec['day-of-week-number']).trim();
    const openStart = !sd || sd === 'now';
    const openEnd = !ed || ed === 'never';
    let dates = '';
    if (!openStart || !openEnd) {
      dates = sd && sd === ed ? dateLabel(sd) : `${openStart ? 'Now' : dateLabel(sd)} to ${openEnd ? 'no end date' : dateLabel(ed)}`;
    }
    const allDay = (!st || st === '00:00') && (!et || et === '23:59');
    const times = allDay ? '' : `${clockLabel(st || '00:00')} to ${clockLabel(et || '23:59')}`;
    const key = `${dates}|${times}`;
    const g = groups.get(key) ?? { dates, times, days: [], everyDay: false };
    const d = Number(dow);
    if (dow && dow !== '*' && Number.isInteger(d) && d >= 0 && d <= 6) g.days.push(d);
    else g.everyDay = true;
    groups.set(key, g);
  }
  const parts = Array.from(groups.values())
    .map((g) => [g.dates, g.everyDay || !g.days.length ? '' : daysLabel(g.days), g.times].filter(Boolean).join(', '))
    .filter(Boolean);
  return parts.length ? parts.join('; ') : 'All day, every day';
}

function ruleCaption(rule: NsRecord, frames: Map<string, FrameInfo>): string {
  const tf = frameOf(rule);
  if (tf === '*') return 'Matches at all times.';
  const schedule = scheduleSummary(rule.time_range_data ?? rule['time-range-data']);
  const f = frames.get(tf);
  const kind = f ? `${f.personal ? 'Personal' : 'Domain'} time frame${FRAME_TYPE[f.type] ? `: ${FRAME_TYPE[f.type]}` : ''}` : '';
  return [schedule, kind].filter(Boolean).join(' · ');
}

// ---------------------------------------------------------------------------
// Destinations
// ---------------------------------------------------------------------------

const SIP_URI = /^(?:sips?:)?[A-Za-z0-9_.+*#-]+@[A-Za-z0-9_.-]+$/;
const DIAL_STRING = /^\+?[0-9*#]+$/;
const EXTENSION_TEXT = /^[A-Za-z0-9_.*#+-]+$/;

function paramsText(params: Param[]): string {
  return params.map((p) => (String(p) === OWN_DEVICES ? OWN_DEVICES_LABEL : String(p))).join(', ');
}

function tokens(text: string): string[] {
  return text
    .split(/[,\n]+/)
    .map((t) => t.trim())
    .filter(Boolean);
}

function sameParams(a: Param[], b: Param[]): boolean {
  return a.length === b.length && a.every((p, i) => String(p) === String(b[i]));
}

/** One destination as the switch stores it, or null when it is not one. */
function normalizeDestination(raw: string, simRing: boolean): string | null {
  let t = raw.trim();
  if (simRing && (t === OWN_DEVICES || t.toLowerCase() === OWN_DEVICES_LABEL.toLowerCase())) return OWN_DEVICES;
  let delay = '';
  if (simRing) {
    const m = /^(.*?)\s*;\s*delay\s*=\s*(\d{1,3})$/i.exec(t);
    if (m) {
      t = m[1].trim();
      delay = `;delay=${Number(m[2])}`;
    }
  }
  if (!t) return null;
  if (SIP_URI.test(t)) return t + delay;
  // A phone number may be typed with spaces, dots, dashes or parentheses.
  const dial = t.replace(/[\s().-]/g, '');
  if (dial && DIAL_STRING.test(dial)) return dial + delay;
  if (EXTENSION_TEXT.test(t)) return t + delay;
  return null;
}

type Parsed = { ok: true; params: string[] } | { ok: false; message: string };

function parseDestinations(text: string, def: OptionDef): Parsed {
  const list = tokens(text);
  if (!list.length) return { ok: false, message: 'Add a destination, or turn this option off.' };
  if (def.params === 'one' && list.length > 1) return { ok: false, message: 'Forward to one destination only.' };
  const out: string[] = [];
  for (const t of list) {
    const v = normalizeDestination(t, def.key === SIM_RING);
    if (!v) {
      return {
        ok: false,
        message:
          def.params === 'one'
            ? `"${t}" is not valid here. Use an extension, a phone number or user@domain.`
            : `"${t}" is not valid here. Use extensions, phone numbers or user@domain, separated by commas.`,
      };
    }
    if (!out.includes(v)) out.push(v);
  }
  return { ok: true, params: out };
}

// ---------------------------------------------------------------------------
// Drafts and the save plan
// ---------------------------------------------------------------------------

interface OptionDraft {
  on: boolean;
  text: string;
}

interface RuleDraft {
  enabled: boolean;
  options: Record<string, OptionDraft>;
}

function draftFromRule(rule: NsRecord): RuleDraft {
  const options: Record<string, OptionDraft> = {};
  for (const def of OPTIONS) {
    const s = readOption(rule, def.key);
    options[def.key] = { on: s.on, text: paramsText(s.params) };
  }
  return { enabled: ruleEnabled(rule), options };
}

interface SavePlan {
  /** The PUT body: the whole rule, with the changed options at their new values. */
  body: Record<string, unknown>;
  changed: string[];
  problems: Record<string, string>;
  dirty: boolean;
  invalid: boolean;
}

function planSave(rule: NsRecord, draft: RuleDraft): SavePlan {
  const body: Record<string, unknown> = { enabled: draft.enabled ? 'yes' : 'no' };
  const changed: string[] = [];
  const problems: Record<string, string> = {};
  for (const def of OPTIONS) {
    const was = readOption(rule, def.key);
    const now = draft.options[def.key] ?? { on: was.on, text: paramsText(was.params) };
    if (def.params === 'none') {
      if (now.on !== was.on) {
        body[def.key] = { enabled: now.on ? 'yes' : 'no' };
        changed.push(def.key);
      }
      continue;
    }
    if (!now.on) {
      // Turning an option off clears its destinations, as the host's own editor does.
      if (was.on) {
        body[def.key] = { enabled: 'no', parameters: [] };
        changed.push(def.key);
      }
      continue;
    }
    const sameText = tokens(now.text).join(',') === tokens(paramsText(was.params)).join(',');
    if (sameText && was.on) continue;
    let params: Param[];
    if (sameText && was.params.length) {
      // Switched back on without editing: send the stored destinations as they were.
      params = was.params;
    } else {
      const parsed = parseDestinations(now.text, def);
      if (!parsed.ok) {
        problems[def.key] = parsed.message;
        continue;
      }
      if (was.on && sameParams(parsed.params, was.params)) continue;
      params = parsed.params;
    }
    body[def.key] = { enabled: 'yes', parameters: params };
    changed.push(def.key);
  }
  const invalid = Object.keys(problems).length > 0;
  const dirty = draft.enabled !== ruleEnabled(rule) || changed.length > 0 || invalid;

  // Send the whole rule, as the host's own editor does, so nothing we did not
  // touch can be switched off if the switch replaces rather than merges.
  const full: Record<string, unknown> = { 'time-frame': frameOf(rule), enabled: body.enabled };
  for (const def of OPTIONS) {
    if (def.key in body) {
      full[def.key] = body[def.key];
      continue;
    }
    const stored = rule[def.key];
    if (stored && typeof stored === 'object' && !Array.isArray(stored)) full[def.key] = stored;
    else full[def.key] = def.params === 'none' ? { enabled: 'no' } : { enabled: 'no', parameters: [] };
  }
  for (const key of extraOptionKeys(rule)) full[key] = rule[key];
  return { body: full, changed, problems, dirty, invalid };
}

/** Why the re-read does not show the saved change, or null when it does. */
function notApplied(after: NsRecord | undefined, plan: SavePlan): string | null {
  if (!after) return 'The phone system accepted the request, but this rule is no longer listed.';
  const missed: string[] = [];
  const wantOn = plan.body.enabled === 'yes';
  if (wantOn ? explicitNo(after.enabled) : yes(after.enabled)) missed.push('Enabled');
  for (const key of plan.changed) {
    const want = (plan.body[key] as { enabled?: unknown }).enabled === 'yes';
    if (readOption(after, key).on !== want) missed.push(optionLabel(key));
  }
  return missed.length ? `The phone system accepted the request but did not apply: ${missed.join(', ')}.` : null;
}

/** Options this save did not touch that were on before it and read as off after it. */
function switchedOff(before: NsRecord, after: NsRecord | undefined, plan: SavePlan): string[] {
  if (!after) return [];
  const keys = [...OPTIONS.map((o) => o.key), ...extraOptionKeys(before)];
  return keys
    .filter((k) => !plan.changed.includes(k) && readOption(before, k).on && !readOption(after, k).on)
    .map(optionLabel);
}

// ---------------------------------------------------------------------------
// Section
// ---------------------------------------------------------------------------

export function CallHandlingSection({ user }: { user: string }) {
  const { Box, Stack, Typography, Alert } = useKit();
  const { api, domain, refresh } = useSwitchboard();
  const { run, isPending, notify } = useActions();

  const [rules, setRules] = useState<NsAnswerRule[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [frames, setFrames] = useState<Map<string, FrameInfo>>(() => new Map());
  const [drafts, setDrafts] = useState<Record<string, RuleDraft>>({});
  const [loadTick, setLoadTick] = useState(0);
  /** Bumped by every read (and on unmount): a late answer is dropped. */
  const request = useRef(0);

  // One read when the tab opens (and per Retry). Time frames are only fetched
  // when a rule uses one, which the default rule does not.
  useEffect(() => {
    const id = ++request.current;
    setRules(null);
    setError(null);
    setNotice(null);
    void (async () => {
      try {
        const rows = await ns.readAnswerRules(api, domain, user);
        if (id !== request.current) return;
        setRules(sortRules(rows));
        if (rows.some((r) => frameOf(r) && frameOf(r) !== '*')) {
          const list = await ns.readTimeframes(api, domain, user);
          if (id === request.current) setFrames(indexFrames(list, user));
        }
      } catch (err) {
        if (id !== request.current) return;
        setRules([]);
        setError(
          classifyError(err) === 'not-found'
            ? 'The phone system did not find answering rules for this extension.'
            : describeReadError('the answering rules', err),
        );
      }
    })();
    return () => {
      request.current += 1;
    };
  }, [api, domain, user, loadTick]);

  const reread = async (): Promise<NsAnswerRule[] | null> => {
    const id = ++request.current;
    try {
      const rows = await ns.readAnswerRules(api, domain, user);
      if (id !== request.current) return null;
      setRules(sortRules(rows));
      setNotice(null);
      return rows;
    } catch (err) {
      if (id === request.current) setNotice(`Saved, but the rules could not be reloaded. ${describeError(err)}`);
      return null;
    }
  };

  const editRule = (rule: NsAnswerRule, update: (d: RuleDraft) => RuleDraft) => {
    const tf = frameOf(rule);
    setDrafts((prev) => ({ ...prev, [tf]: update(prev[tf] ?? draftFromRule(rule)) }));
  };

  const discard = (rule: NsAnswerRule) => {
    const tf = frameOf(rule);
    setDrafts((prev) => {
      const next = { ...prev };
      delete next[tf];
      return next;
    });
  };

  const save = async (rule: NsAnswerRule) => {
    const tf = frameOf(rule);
    const draft = drafts[tf];
    if (!draft) return;
    const plan = planSave(rule, draft);
    if (!plan.dirty || plan.invalid) return;
    const outcome = { reloaded: false, alsoOff: [] as string[], gone: false };
    const ok = await run(
      `handling:${user}:${tf}`,
      async () => {
        try {
          await ns.updateAnswerRule(api, domain, user, tf, plan.body);
        } catch (err) {
          if (classifyError(err) !== 'not-found') throw err;
          outcome.gone = true;
          throw new Error('This rule is no longer on the phone system, so the list has been reloaded.');
        }
        const fresh = await reread();
        if (!fresh) return;
        outcome.reloaded = true;
        const after = fresh.find((r) => frameOf(r) === tf);
        const problem = notApplied(after, plan);
        if (problem) throw new Error(problem);
        outcome.alsoOff = switchedOff(rule, after, plan);
      },
      { success: 'Call handling saved', failure: 'Could not save call handling.' },
    );
    if (!ok) {
      if (outcome.gone) {
        discard(rule);
        setLoadTick((t) => t + 1);
      }
      return;
    }
    if (outcome.reloaded) discard(rule);
    if (outcome.alsoOff.length) {
      notify('info', `The phone system now also shows ${outcome.alsoOff.join(', ')} as off in the ${frameLabel(tf)} rule.`);
    }
    if (plan.changed.includes(DND)) refresh(['users']);
  };

  let body: React.ReactNode;
  if (rules === null) {
    body = (
      <Stack spacing={1} aria-busy="true">
        <Typography variant="caption" color="text.secondary" role="status">
          Loading call handling...
        </Typography>
        {[0, 1].map((i) => (
          <Box
            key={i}
            sx={{
              height: 120,
              borderRadius: 1.5,
              bgcolor: 'action.hover',
              animation: 'tvsbRulePulse 1.4s ease-in-out infinite',
              '@keyframes tvsbRulePulse': { '0%, 100%': { opacity: 1 }, '50%': { opacity: 0.45 } },
            }}
          />
        ))}
      </Stack>
    );
  } else if (error) {
    body = (
      <Alert
        severity="error"
        title="Call handling could not be loaded"
        message={error}
        action={{ label: 'Retry', onClick: () => setLoadTick((t) => t + 1) }}
      />
    );
  } else if (!rules.length) {
    body = <Empty>No answering rules are set up for this extension.</Empty>;
  } else {
    body = (
      <Stack spacing={2}>
        {rules.map((rule, i) => {
          const tf = frameOf(rule);
          const draft = drafts[tf] ?? draftFromRule(rule);
          return (
            <RuleCard
              key={tf || `rule-${i}`}
              rule={rule}
              draft={draft}
              plan={planSave(rule, draft)}
              caption={ruleCaption(rule, frames)}
              busy={isPending(`handling:${user}:${tf}`)}
              onEnabled={(on) => editRule(rule, (d) => ({ ...d, enabled: on }))}
              onOption={(key, value) => editRule(rule, (d) => ({ ...d, options: { ...d.options, [key]: value } }))}
              onDiscard={() => discard(rule)}
              onSave={() => void save(rule)}
            />
          );
        })}
      </Stack>
    );
  }

  return (
    <Stack spacing={1.5}>
      <Typography variant="body2" color="text.secondary">
        Listed in the order the phone system checks them. The first enabled rule whose time frame matches handles the call.
      </Typography>
      {notice ? (
        <Alert
          severity="warning"
          message={notice}
          onClose={() => setNotice(null)}
          action={{ label: 'Reload', onClick: () => setLoadTick((t) => t + 1) }}
        />
      ) : null}
      {body}
    </Stack>
  );
}

// ---------------------------------------------------------------------------
// Pieces
// ---------------------------------------------------------------------------

function RuleCard({
  rule,
  draft,
  plan,
  caption,
  busy,
  onEnabled,
  onOption,
  onDiscard,
  onSave,
}: {
  rule: NsAnswerRule;
  draft: RuleDraft;
  plan: SavePlan;
  caption: string;
  busy: boolean;
  onEnabled: (on: boolean) => void;
  onOption: (key: string, value: OptionDraft) => void;
  onDiscard: () => void;
  onSave: () => void;
}) {
  const { Paper, Stack, Box, Typography, Switch, Divider, Icon } = useKit();
  const tf = frameOf(rule);
  const activeNow = rule['is-active'] === true || yes(rule['is-active']);
  const extras = extraOptionKeys(rule);
  return (
    <Paper variant="outlined" sx={{ p: 2 }}>
      <Stack direction="row" spacing={1.5} alignItems="flex-start">
        <Box sx={{ color: 'primary.main', display: 'flex', pt: 0.25 }} aria-hidden>
          <Icon name={tf === '*' ? 'lucide:calendar-check' : 'lucide:calendar-clock'} size={18} />
        </Box>
        <Box sx={{ flex: 1, minWidth: 0 }}>
          <Stack direction="row" spacing={1} alignItems="center" sx={{ flexWrap: 'wrap', rowGap: 0.5 }}>
            <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
              {frameLabel(tf)}
            </Typography>
            {activeNow ? <Pill tone="success" label="Active now" /> : null}
            {plan.dirty ? <Pill tone="warning" outlined label="Unsaved changes" /> : null}
          </Stack>
          {caption ? (
            <Typography variant="caption" color="text.secondary" component="div">
              {caption}
            </Typography>
          ) : null}
        </Box>
        <Switch label="Enabled" checked={draft.enabled} disabled={busy} onChange={(_e, checked) => onEnabled(checked)} />
      </Stack>
      <Divider sx={{ my: 1.5 }} />
      <Stack spacing={1.25} divider={<Divider flexItem />} sx={{ opacity: draft.enabled ? 1 : 0.65 }}>
        {OPTIONS.map((def) => (
          <OptionRow
            key={def.key}
            def={def}
            value={draft.options[def.key] ?? { on: false, text: '' }}
            problem={plan.problems[def.key]}
            disabled={busy}
            onChange={(v) => onOption(def.key, v)}
          />
        ))}
        {extras.map((key) => (
          <ReadOnlyRow key={key} label={optionLabel(key)} state={readOption(rule, key)} />
        ))}
      </Stack>
      <Stack direction="row" spacing={1} alignItems="center" justifyContent="flex-end" sx={{ mt: 2, flexWrap: 'wrap', rowGap: 1 }}>
        {plan.invalid ? (
          <Typography variant="caption" color="error.main">
            Fix the highlighted entry to save.
          </Typography>
        ) : null}
        {plan.dirty ? <SmallButton variant="text" color="inherit" label="Discard changes" onClick={onDiscard} disabled={busy} /> : null}
        <SmallButton
          variant="contained"
          icon="lucide:save"
          label="Save changes"
          onClick={onSave}
          disabled={!plan.dirty || plan.invalid}
          busy={busy}
        />
      </Stack>
    </Paper>
  );
}

function OptionRow({
  def,
  value,
  problem,
  disabled,
  onChange,
}: {
  def: OptionDef;
  value: OptionDraft;
  problem: string | undefined;
  disabled: boolean;
  onChange: (value: OptionDraft) => void;
}) {
  const { Box, Stack, Typography, Switch, TextField } = useKit();
  const toggle = (on: boolean) =>
    // Turning simultaneous ring on with nothing listed starts from "Your devices".
    onChange({ on, text: on && !value.text.trim() && def.key === SIM_RING ? OWN_DEVICES_LABEL : value.text });
  return (
    <Box>
      <Stack direction="row" spacing={2} alignItems="center" justifyContent="space-between">
        <Box sx={{ minWidth: 0 }}>
          <Typography variant="body2" sx={{ fontWeight: 600 }}>
            {def.label}
          </Typography>
          <Typography variant="caption" color="text.secondary" component="div">
            {def.hint}
          </Typography>
        </Box>
        <Switch
          checked={value.on}
          disabled={disabled}
          onChange={(_e, checked) => toggle(checked)}
          slotProps={{ input: { 'aria-label': def.label } }}
        />
      </Stack>
      {def.field && value.on ? (
        <TextField
          size="small"
          fullWidth
          label={def.field.label}
          placeholder={def.field.placeholder}
          value={value.text}
          disabled={disabled}
          error={!!problem}
          helperText={problem ?? def.field.helper}
          onChange={(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => onChange({ ...value, text: e.target.value })}
          sx={{ mt: 1 }}
        />
      ) : null}
    </Box>
  );
}

function ReadOnlyRow({ label, state }: { label: string; state: OptionState }) {
  const { Box, Stack, Typography } = useKit();
  const text = paramsText(state.params);
  return (
    <Stack direction="row" spacing={2} alignItems="center" justifyContent="space-between">
      <Box sx={{ minWidth: 0 }}>
        <Typography variant="body2" sx={{ fontWeight: 600 }}>
          {label}
        </Typography>
        <Typography variant="caption" color="text.secondary" component="div">
          {text || 'Shown as the phone system reports it.'}
        </Typography>
      </Box>
      <Stack direction="row" spacing={1} alignItems="center">
        <Pill tone={state.on ? 'success' : 'neutral'} label={state.on ? 'On' : 'Off'} />
        <Pill
          outlined
          label="Read only"
          title="The switchboard shows this option but does not change it. Change it in the phone system portal."
        />
      </Stack>
    </Stack>
  );
}
